{"answer":"#!/usr/bin/env python3
import tomllib


def main():
    path = '/etc/orders/limits.toml'
    with open(path, 'rb') as f:
        data = tomllib.load(f)
    pool = data.get('pool', {})
    value = None
    for key in ('limit', 'connection_limit', 'connections_limit'):
        if key in pool:
            value = pool[key]
            break
    if value is None:
        for v in pool.values():
            if isinstance(v, int):
                value = v
                break
            if isinstance(v, str):
                v_str = v.strip()
                if v_str.isdigit() or (v_str.startswith('-') and v_str[1:].isdigit()):
                    try:
                        value = int(v_str)
                        break
                    except ValueError:
                        pass
    if value is None:
        raise SystemExit('connection limit not found in [pool]')
    print(int(value))

main()
