{"answer":"import tomllib
import sys


def main():
    path = '/etc/orders/limits.toml'
    try:
        with open(path, 'rb') as f:
            data = tomllib.load(f)
    except FileNotFoundError:
        print(f'Limits file not found: {path}', file=sys.stderr)
        raise
    pool = data.get('pool')
    if not isinstance(pool, dict):
        print('Invalid or missing [pool] table in limits.toml', file=sys.stderr)
        raise SystemExit(1)
    for key in ('limit','connections','connection_limit','max_connections','pool_limit'):
        if key in pool:
            try:
                value = int(pool[key])
            except (TypeError, ValueError):
                print(f'Invalid value for {key} in [pool] table: {pool[key]!r}', file=sys.stderr)
                raise SystemExit(1)
            print(value)
            return
    print('No limit key found in [pool] table', file=sys.stderr)
    raise SystemExit(1)


if __name__ == '__main__':
    main()
